  "acc.issuedTitle": "Обліковий запис видано — {name}",
  "acc.issuedBody": "PIN: {pin}\n\nЛюдина вводить своє ім'я і цей PIN на своєму пристрої. PIN завжди можна переглянути в цьому списку.",
  "acc.couldNotIssue": "Не вдалося видати",
  "acc.deleteQ": "Видалити цей обліковий запис?",
  "acc.deleteBody": "{name} буде назавжди видалено зі списку, і PIN більше ніколи не спрацює.",
  "acc.deleteUsed": "Його використовували на пристроях: {devices}. Вони лишаються в «Пристроях», доки ви їх там не видалите (Пристрої → пристрій → Видалити зі списку).",
