  "acc.couldNotRename": "Не вдалося перейменувати",
  "acc.removeQ": "Видалити цей пристрій?",
  "acc.removeBody": "{who} буде видалено зі списку, і доступ зникне одразу.\n\nЗапис про пристрій стирається, а не вимикається, і пристрій зможе приєднатися знову за новим запрошенням. Уже підписані з нього огляди не змінюються — у них записано підпис, а не пристрій.",
  "acc.couldNotRemove": "Не вдалося видалити",
  "acc.approved": "схвалено",
  "acc.waitingApproval": "чекає схвалення",
  "acc.waitingLc": "чекає",
  "acc.switchedOffLc": " · вимкнено",
  "acc.youUse": "\n\nЦе пристрій, яким ви користуєтеся.",
  "acc.onlyMaster": "\n\nСхвалити, змінити роль або видалити пристрій може лише капітан.",
  "acc.approve": "Схвалити",
  "acc.rename": "Перейменувати",
  "acc.make": "Зробити: {role}",
  "acc.switchOn": "Увімкнути",
  "acc.switchOff": "Вимкнути",
  "acc.removeFromList": "Видалити зі списку",
  "acc.thisDeviceLc": " · цей пристрій",
  "acc.lastMaster": "\n\nЦе єдиний капітан на судні, тому його роль не можна змінити і його не можна вимкнути — не залишиться нікого, хто міг би це скасувати. Спершу зробіть капітаном інший пристрій, тоді цей можна буде змінювати.",
  "acc.title": "Облікові записи",
  "acc.sub": "Хто може користуватися журналом цього судна",
  "acc.imoRequired": "Потрібен номер ІМО судна",
  "acc.imoBody": "Облікові записи видаються для судна, а судно визначається номером ІМО. Спершу вкажіть його в Налаштування → Судно.",
  "acc.subMaster": "Видача, відкликання і схвалення",
  "acc.subCrew": "Хто на борту цього судна",
  "acc.rankUnknown": "З'ясовуємо права цього пристрою",
  "acc.rankUnknownBody": "Облікові записи відкриються, коли судно підтвердить роль цього пристрою. Якщо так і лишається, пристрій ще не приєднано — див. картку «Цей пристрій» угорі Налаштувань.",
  "acc.readOnly": "{role} — лише перегляд",
  "acc.readOnlyBody": "Облікові записи, схвалення і ролі — у капітана. Ваш пристрій — його ім'я, роль і схвалення — у Налаштування → Цей пристрій.",
  "acc.invitationsN": "Запрошення ({n})",
  "acc.devicesN": "Пристрої ({n})",
  "acc.issue": "Видати обліковий запис",
  "acc.noInvites": "Облікові записи ще не видавалися.",
  "acc.revoked": "Відкликано",
  "acc.unused": "Не використано",
  "acc.olderBody": "Та сама людина з тією ж роллю і таким самим пристроєм приєдналася знову — з іншої адреси браузера, після очищення браузера або з перевстановленого телефона. Лишається останнє активне (цей пристрій — завжди). Сервер сам вимикає такі підключення через три дні без використання; якщо відкрити знову — воно повернеться.",
  "acc.switchOffOlderQ": "Вимкнути старі підключення?",
