  "acc.renameWho": "Перейменувати: {who}",
  "acc.issueNote": "Ім'я і PIN, які людина вводить на своєму пристрої. PIN показується після видачі та зберігається в «Запрошеннях».",
  "acc.rankPh": "Посада на борту (третій помічник, боцман…) — необов'язково",
  "acc.issueBtn": "Видати",
  "acc.renameTitle": "Перейменувати пристрій",
  "acc.renameNote": "Як цей пристрій називається у списку та на його картці «Цей пристрій». Для спільного комп'ютера, що переходить з рук у руки при кожній зміні екіпажу, вкажіть посаду — «Третій помічник».",
  "acc.renameSignDevice": "Це судно підписує огляди обліковим записом пристрою, тому саме це ім'я стоятиме в наступному обході, підписаному на цьому пристрої, і в його звіті. Перейменуйте при зміні екіпажу — підпис одразу зміниться. Уже підписані огляди зберігають попереднє ім'я.",
  "acc.renameSignCrew": "На підписи це не впливає — того, хто підписує, обирають зі списку екіпажу під час підписання обходу, а вже підписані огляди зберігають своє ім'я.",
